sys_script_include.script:
var TBA_TravelBuddyRatingUtils = Class.create();
TBA_TravelBuddyRatingUtils.prototype = {
    initialize: function() {
    },

	calculateAverage: function(buddyId){

		//Aggregate for fast execution
		var ga =new GlideAggregate('x_travel_buddy_app_travel_trip_feedback');
		// for specific buddy only
		ga.addQuery('u_buddy_name', buddyId);
		// calculation AVG on Rating Field
		ga.addAggregate('AVG','u_ratings');
		ga.setGroup(false);
		ga.query();

		//storing Total Rating to tranfer it in user records 
		var average = 0;
		if(ga.next()){
			average= ga.getAggregate('AVG', 'u_ratings');
			gs.info('value of average = '+ average);
			// Round the math to 1 decimal place eg. [4.7]
			average = Math.round(parseFloat(average) * 10) / 10;
		}

		//updating Rating field for Buddy(user table)
		var grUser = new GlideRecord('sys_user');
		if(grUser.get(buddyId)){
			grUser.setValue('x_travel_buddy_app_u_total_rating', average);
			grUser.update();
		}

	},

    type: 'TBA_TravelBuddyRatingUtils'
};
